public class JCharAt1 {
	public static void main(String[] args) {
		//Step 1: Extract the characters from the string
		String str = "String Example!";
		char ch1 = str.charAt(0);
		char ch2 = str.charAt(8);
		char ch3 = str.charAt(str.length()-1);
		//Step 2: Print the extracted characters
		System.out.println("The 1st character: " + ch1);
		System.out.println("The 9th character: " + ch2);
		System.out.println("The last character: " + ch3);
	}
}
